from gen import *
V="verb"; N="noun"; A="adjective"; AD="adverb"; P="phrase"
T(63,1,"Був, була, були","Сказати, де ви були й який був стан.",
 "Минулий час дієслова to be: I, he, she, it — was; we, you, they — were. I was at home. They were late. Заперечення: wasn't, weren't. Питання: Were you at home? — Yes, I was. Born — народжений: I was born in 1998.",
 [W("was","/wɒz/",V,"був, була, було","I was at home yesterday.","Учора я був удома."),
  W("were","/wɜː/",V,"були","They were in Paris.","Вони були в Парижі."),
  W("wasn't","/ˈwɒznt/",V,"не був, не була","I wasn't tired.","Я не втомився."),
  W("weren't","/wɜːnt/",V,"не були","We weren't late.","Ми не спізнилися."),
  W("born","/bɔːn/",A,"народжений","I was born in 1998.","Я народився 1998 року.")],
 ("What are you going to do next weekend?","Повторимо. Піду в похід. Що відповісти?",["I'm going to go on a hike.","I go on hike next weekend.","I am going go hike."],"I'm going to go on a hike."),
 [("I was at home yesterday.","Прослухайте. Де була людина вчора?",["Удома","На роботі","У парку"],"Was."),
  ("They were in Paris.","Прослухайте. Де вони були?",["У Парижі","У Лондоні","У Римі"],"Were."),
  ("I was born in 1998.","Прослухайте. Коли народилася людина?",["1998 року","2008 року","1989 року"],"Born.")],
 [("I ___ at home yesterday.",["was","were","am"],"З I — was."),
  ("They ___ in Paris.",["were","was","are"],"З they — were."),
  ("We ___ late. (не)",["weren't","wasn't","aren't"],"З we — weren't.")],
 ("Яка форма з «you» у минулому?",["were","was","wasn't"],"You — were."),
 ("Учора я був удома.",["I","was","at","home","yesterday"],["were","am"],"I was at home yesterday."),
 ("Ми не спізнилися.",["We weren't late"],"We weren't late."),
 ("Were you at home?","Так, був. Що відповісти?",["Yes, I was.","Yes, I were.","Yes, I did."],"Yes, I was."))
T(63,2,"Коли це було","Вказати час у минулому.",
 "Ago — тому (після слова про час): a week ago, two years ago. Last night — минулої ночі, last week — минулого тижня, last month — минулого місяця, last year — минулого року. Перед last прийменник не ставимо: I was there last year.",
 [W("ago","/əˈɡəʊ/",AD,"тому (час)","I was there two years ago.","Я був там два роки тому."),
  W("last night","/ˈlɑːst naɪt/",P,"минулої ночі, вчора ввечері","I was tired last night.","Минулого вечора я був утомлений."),
  W("last week","/ˈlɑːst wiːk/",P,"минулого тижня","We were in Rome last week.","Минулого тижня ми були в Римі."),
  W("last month","/ˈlɑːst mʌnθ/",P,"минулого місяця","She was ill last month.","Минулого місяця вона хворіла."),
  W("last year","/ˈlɑːst jɪə/",P,"минулого року","It was cold last year.","Минулого року було холодно.")],
 ("Were you at home?","Повторимо. Так, був. Що відповісти?",["Yes, I was.","Yes, I were.","Yes, I did."],"Yes, I was."),
 [("I was there two years ago.","Прослухайте. Коли людина там була?",["Два роки тому","Через два роки","Минулого року"],"Ago."),
  ("We were in Rome last week.","Прослухайте. Де вони були?",["У Римі","У Парижі","У Мілані"],"Rome."),
  ("She was ill last month.","Прослухайте. Коли вона хворіла?",["Минулого місяця","Минулого тижня","Минулого року"],"Last month.")],
 [("I was there two years ___.",["ago","last","before"],"Two years ago."),
  ("We were in Rome ___ week.",["last","ago","in"],"Last week."),
  ("It was cold ___ year.",["last","in last","at"],"Без прийменника: last year.")],
 ("Що означає ago?",["тому (про час)","минулого","завжди"],"Ago — тому."),
 ("Минулого тижня ми були в Римі.",["We","were","in","Rome","last","week"],["was","ago"],"We were in Rome last week."),
 ("Я був там два роки тому.",["I was there two years ago"],"I was there two years ago."),
 ("When were you in Rome?","Минулого тижня. Що відповісти?",["Last week.","In last week.","The last week."],"Last week."))
T(63,3,"Дитинство","Розповісти про дитинство.",
 "Childhood — дитинство, memory — спогад, kid — дитина (розмовне), youth — молодість, baby — немовля. Приклад: I was a happy kid. In my childhood I was shy. I have a lovely memory of my grandmother.",
 [W("childhood","/ˈtʃaɪldhʊd/",N,"дитинство","I had a happy childhood.","У мене було щасливе дитинство."),
  W("memory","/ˈmeməri/",N,"спогад","This is a lovely memory.","Це чудовий спогад."),
  W("kid","/kɪd/",N,"дитина","I was a shy kid.","Я була сором'язливою дитиною."),
  W("youth","/juːθ/",N,"молодість","In my youth I was fast.","У молодості я був швидким."),
  W("baby","/ˈbeɪbi/",N,"немовля","My brother was a baby then.","Тоді мій брат був немовлям.")],
 ("When were you in Rome?","Повторимо. Минулого тижня. Що відповісти?",["Last week.","In last week.","The last week."],"Last week."),
 [("I had a happy childhood.","Прослухайте. Яке було дитинство?",["Щасливе","Сумне","Довге"],"Happy."),
  ("I was a shy kid.","Прослухайте. Якою була людина в дитинстві?",["Сором'язливою","Веселою","Сильною"],"Shy."),
  ("My brother was a baby then.","Прослухайте. Ким був брат?",["Немовлям","Студентом","Вчителем"],"Baby.")],
 [("I had a happy ___.",["childhood","memory","youth"],"Дитинство."),
  ("This is a lovely ___.",["memory","kid","baby"],"Спогад."),
  ("I ___ a shy kid.",["was","were","am"],"З I — was.")],
 ("Що таке childhood?",["дитинство","молодість","спогад"],"Childhood — дитинство."),
 ("Я була сором'язливою дитиною.",["I","was","a","shy","kid"],["were","baby"],"I was a shy kid."),
 ("Це чудовий спогад.",["This is a lovely memory"],"This is a lovely memory."),
 ("What was your childhood like?","Щасливе. Що відповісти?",["It was happy.","It were happy.","It was happily."],"It was happy."))
T(63,4,"Події в житті","Розповісти про події в житті.",
 "Adventure — пригода, accident — нещасний випадок, dream — мрія, сон, event — подія, experience — досвід. Приклад: It was a big adventure. It was an accident. My dream was to travel.",
 [W("adventure","/ədˈventʃə/",N,"пригода","It was a great adventure.","Це була чудова пригода."),
  W("accident","/ˈæksɪdənt/",N,"нещасний випадок","It was an accident.","Це був нещасний випадок."),
  W("dream","/driːm/",N,"мрія, сон","My dream was to travel.","Моєю мрією було подорожувати."),
  W("event","/ɪˈvent/",N,"подія","It was a big event.","Це була велика подія."),
  W("experience","/ɪkˈspɪəriəns/",N,"досвід","It was a good experience.","Це був добрий досвід.")],
 ("What was your childhood like?","Повторимо. Щасливе. Що відповісти?",["It was happy.","It were happy.","It was happily."],"It was happy."),
 [("It was a great adventure.","Прослухайте. Що каже людина?",["Це була чудова пригода","Це була нудна поїздка","Це була аварія"],"Adventure."),
  ("It was an accident.","Прослухайте. Що каже людина?",["Це був нещасний випадок","Це був план","Це був подарунок"],"Accident."),
  ("My dream was to travel.","Прослухайте. Яка була мрія?",["Подорожувати","Вчитися","Працювати"],"Dream.")],
 [("It was a great ___.",["adventure","accident","event"],"Пригода."),
  ("It was an ___.",["accident","dream","experience"],"Accident."),
  ("It was a good ___.",["experience","accident","kid"],"Experience.")],
 ("Що таке event?",["подія","пригода","мрія"],"Event — подія."),
 ("Моєю мрією було подорожувати.",["My","dream","was","to","travel"],["were","dreams"],"My dream was to travel."),
 ("Це був добрий досвід.",["It was a good experience"],"It was a good experience."),
 ("How was the trip?","Чудова пригода. Що відповісти?",["It was a great adventure.","It were a great adventure.","It was great adventures."],"It was a great adventure."))
T(63,5,"Історія","Говорити про давні часи.",
 "Century — століття, decade — десятиліття, generation — покоління, ancestor — предок, ancient — давній. Приклад: This castle is from the twelfth century. My ancestors were farmers. Ancient Rome was big.",
 [W("century","/ˈsentʃəri/",N,"століття","The castle is from the twelfth century.","Замок із дванадцятого століття."),
  W("decade","/ˈdekeɪd/",N,"десятиліття","It was a decade ago.","Це було десять років тому."),
  W("generation","/ˌdʒenəˈreɪʃn/",N,"покоління","Three generations live here.","Тут живуть три покоління."),
  W("ancestor","/ˈænsestə/",N,"предок","My ancestors were farmers.","Мої предки були фермерами."),
  W("ancient","/ˈeɪnʃənt/",A,"давній","Ancient Rome was big.","Стародавній Рим був великим.")],
 ("How was the trip?","Повторимо. Чудова пригода. Що відповісти?",["It was a great adventure.","It were a great adventure.","It was great adventures."],"It was a great adventure."),
 [("The castle is from the twelfth century.","Прослухайте. З якого століття замок?",["З дванадцятого","З десятого","З двадцятого"],"Twelfth."),
  ("My ancestors were farmers.","Прослухайте. Ким були предки?",["Фермерами","Лікарями","Вчителями"],"Farmers."),
  ("Ancient Rome was big.","Прослухайте. Яким був Рим?",["Великим","Маленьким","Новим"],"Big.")],
 [("The castle is from the twelfth ___.",["century","decade","generation"],"Століття."),
  ("My ___ were farmers.",["ancestors","generation","decade"],"Предки."),
  ("___ Rome was big.",["Ancient","Century","Event"],"Давній.")],
 ("Що таке decade?",["десятиліття","століття","покоління"],"Decade — десятиліття."),
 ("Мої предки були фермерами.",["My","ancestors","were","farmers"],["was","century"],"My ancestors were farmers."),
 ("Це було десять років тому.",["It was a decade ago"],"It was a decade ago."),
 ("Who were your ancestors?","Фермери. Що відповісти?",["They were farmers.","They was farmers.","Farmers they were."],"They were farmers."))
T(63,6,"Повторення: учора","Закріпити was/were і слова про минуле.",
 "Нових слів немає. Повторюємо: was (I, he, she, it) і were (we, you, they), wasn't, weren't; час (ago, last week, last year); дитинство (childhood, memory, kid); події (adventure, accident, experience) і історія (century, ancestor, ancient).",
 [],
 ("Who were your ancestors?","Повторимо. Фермери. Що відповісти?",["They were farmers.","They was farmers.","Farmers they were."],"They were farmers."),
 [("I was born in 1998, and I had a happy childhood.","Прослухайте. Що каже людина?",["Народилася 1998 року, щасливе дитинство","Народилася 1989 року, сумне дитинство","Народилася 1998 року, нудне дитинство"],"Born, happy childhood."),
  ("We weren't late last week.","Прослухайте. Що каже людина?",["Минулого тижня ми не спізнилися","Минулого тижня ми спізнилися","Цього тижня ми не спізнилися"],"Weren't."),
  ("It was a great adventure two years ago.","Прослухайте. Коли була пригода?",["Два роки тому","Минулого року","Минулого місяця"],"Ago.")],
 [("They ___ in Paris last year.",["were","was","are"],"Were."),
  ("I ___ at home last night.",["was","were","am"],"Was."),
  ("It was a decade ___.",["ago","last","before"],"Ago.")],
 ("Яка форма для «вони» в минулому?",["were","was","wasn't"],"Were."),
 ("Учора я був удома.",["I","was","at","home","yesterday"],["were","am"],"I was at home yesterday."),
 ("Це був добрий досвід.",["It was a good experience"],"It was a good experience."),
 ("Where were you last night?","Удома. Що відповісти?",["I was at home.","I were at home.","I was in home."],"I was at home."),
 review=True)
